const raw = $json;
const str = v => typeof v === 'string' ? v : '';
const emailOK = v => typeof v === 'string' && /^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(v);
function address(value) {
 if (typeof value === 'string') {
  const m = value.match(/<([^<>]+)>/);
  return {email:(m ? m[1] : value).trim(), name:m ? value.slice(0,value.indexOf('<')).trim().replace(/^"|"$/g,'') : ''};
 }
 const first = value?.value?.[0] || value || {};
 return {email:str(first.address), name:str(first.name)};
}
const from = address(raw.from);
let senderName = from.name, senderEmail = from.email;
let subject = str(raw.subject), body = str(raw.textPlain) || str(raw.text);
let source = 'email';
let popupRequestId = ''; 
const transportText = body || str(raw.textHtml) || str(raw.html);
const isFormspree = /@(?:[a-z0-9-]+\.)*formspree\.(?:io|com)$/i.test(from.email)
 || /Someone just submitted your form/i.test(transportText)
 || /JOIN_REQUEST_V1_BEGIN/.test(transportText);
if (isFormspree) {
 source = 'formspree';
 const matches = [...transportText.matchAll(/JOIN_REQUEST_V1_BEGIN([\s\S]*?)JOIN_REQUEST_V1_END/g)];
 if (matches.length !== 1) throw new Error('Formspree: eindeutige Nutzdaten fehlen. Neue stakeholder.js verwenden und neu senden. Kein Ticket angelegt.');
 let p;
 try { p = JSON.parse(decodeURIComponent(matches[0][1].replace(/\s/g,''))); }
 catch { throw new Error('Formspree-Nutzdaten beschädigt; kein Ticket angelegt.'); }
 if (!p || p.version !== 1 || typeof p.name !== 'string' || !p.name.trim()
   || typeof p.subject !== 'string' || typeof p.message !== 'string' || !emailOK(p.email)) {
   throw new Error('Formspree-Pflichtfelder ungültig; kein Ticket angelegt.');
 }
 popupRequestId = typeof p.requestId === 'string' ? p.requestId : '';
 senderName = p.name.trim(); senderEmail = p.email.trim(); subject = p.subject; body = p.message;
} else if (!body) {
 throw new Error('Keine Klartext-Nachricht vorhanden. HTML-only-Mail vor Verarbeitung in Klartext umwandeln.');
}
body = (s => {
 const pairs = [['\u00c3\u00a4','ä'],['\u00c3\u00b6','ö'],['\u00c3\u00bc','ü'],['\u00c3\u0084','Ä'],['\u00c3\u201e','Ä'],['\u00c3\u0096','Ö'],['\u00c3\u2013','Ö'],['\u00c3\u009c','Ü'],['\u00c3\u0153','Ü'],['\u00c3\u009f','ß'],['\u00c3\u0178','ß']];
 for (const [bad, good] of pairs) s = s.split(bad).join(good);
 return s;
})(body);
if (!emailOK(senderEmail) || !subject.trim() || !body.trim()) throw new Error('Absender, Betreff oder Nachricht fehlen; kein Ticket angelegt.');
if (body.length > 50000 || subject.length > 500) throw new Error('Nachricht zu lang; manuell prüfen.');
if (/\uFFFD/.test(body)) throw new Error('Nachricht enthält verlorene Zeichen (�); Originalmail prüfen.');
const parsedDate = new Date(raw.date);
const stamp = raw.date && Number.isFinite(parsedDate.getTime()) ? parsedDate : new Date();
const parts = new Intl.DateTimeFormat('en', {timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(stamp);
const part = type => parts.find(p=>p.type===type).value;
const referenceDate = `${part('year')}-${part('month')}-${part('day')}`;
const h = raw.headers || raw.metadata || {};
const headerId = Array.isArray(h) ? h.find(x => String(x.key || x.name).toLowerCase() === 'message-id')?.value : (h['message-id'] || h['Message-ID']);
const messageId = str(raw.messageId) || str(raw.messageID) || str(headerId);
return {json:{senderName,senderEmail,subject,body,source,referenceDate,messageId,popupRequestId,mailTimestamp:str(raw.date)}};

const mail = $json;
let identity;
if (mail.source === 'formspree' && /^[0-9a-f-]{36}$/i.test(mail.popupRequestId || '')) {
 identity = 'popup:' + mail.popupRequestId;
} else if (mail.messageId) {
 identity = 'mail:' + mail.senderEmail.toLowerCase() + ':' + mail.messageId;
} else if (mail.mailTimestamp && Number.isFinite(Date.parse(mail.mailTimestamp))) {
 // Compatibility fallback for IMAP outputs without Message-ID.
 identity = JSON.stringify([mail.senderEmail.toLowerCase(),mail.mailTimestamp,mail.subject,mail.body]);
} else {
 throw new Error('Keine stabile Anfrage-ID und kein Mailzeitstempel. Mail-OUTPUT prüfen; kein KI-Aufruf.');
}
const { createHash } = require('crypto');
const requestKey = createHash('sha256').update(identity + JSON.stringify([mail.senderEmail.toLowerCase(),mail.subject,mail.body])).digest('hex');
return {json:{...mail,requestKey}};

const DAILY_LIMIT = 50;
const mail = $('Prepare limit request').item.json;
if ($json.statusCode !== 200) throw new Error('Tageslimit konnte nicht gelesen werden.');
const headers = $json.headers || {};
const etag = headers.etag || headers.ETag;
if (!etag) throw new Error('Firebase-ETag fehlt. Kein ungesichertes Schreiben erlaubt.');
const input = $json.body;
const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);
if (input !== null && !object(input)) throw new Error('Ungültiger requestLimits-Datensatz.');
const document = input === null ? {days:{},requests:{}} : JSON.parse(JSON.stringify(input));
if (document.days === undefined) document.days = {};
if (document.requests === undefined) document.requests = {};
if (!object(document.days) || !object(document.requests)) throw new Error('Ungültige Zählerstruktur.');
// Current processing day in Berlin; refreshed on every CAS retry.
const parts = new Intl.DateTimeFormat('en',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
const p = key => parts.find(x=>x.type===key).value;
const day = `${p('year')}-${p('month')}-${p('day')}`;
const current = document.days[day];
const count = current === undefined ? 0 : current.count;
if (!Number.isInteger(count) || count < 0) throw new Error('Tageszähler ungültig; manuell prüfen.');
const existing = document.requests[mail.requestKey];
if (existing !== undefined) {
 if (!object(existing) || typeof existing.day !== 'string') throw new Error('Reservierung ungültig.');
 return {json:{...mail,quotaAllowed:true,quotaWriteNeeded:false,dailyRequestCount:count,quotaDay:day,reusedReservation:true}};
}
if (count >= DAILY_LIMIT) return {json:{...mail,quotaAllowed:false,quotaWriteNeeded:false,dailyRequestCount:count,quotaDay:day}};
if ($runIndex >= 6) throw new Error('Zu viele gleichzeitige Reservierungen. Später erneut ausführen; keine KI gestartet.');
document.days[day] = {count:count+1};
document.requests[mail.requestKey] = {day};
return {json:{...mail,quotaAllowed:true,quotaWriteNeeded:true,quotaDay:day,dailyRequestCount:count+1,quotaETag:etag,quotaDocument:document}};

const previous = $('Decide limit reservation').item.json;
if ($json.statusCode === 412) return {json:{retryReservation:true}};
if ($json.statusCode !== 200) throw new Error('Firebase-Reservierung fehlgeschlagen (HTTP ' + $json.statusCode + '). Keine KI gestartet.');
const {quotaDocument, quotaETag, ...result} = previous;
return {json:{...result,retryReservation:false}};

const mail = $('Prepare limit request').item.json;
if ($json.quotaAllowed !== true) throw new Error('Keine gültige Reservierung.');
return {json:{...mail,dailyRequestCount:$json.dailyRequestCount,quotaDay:$json.quotaDay}};

