const mail = $('Extract data').item.json;
let ai = $json.output;
if (typeof ai === 'string') {
  ai = JSON.parse(ai.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''));
}
if (!ai || typeof ai !== 'object' || Array.isArray(ai)) throw new Error('KI-Ausgabe fehlt oder ist kein Objekt.');
const clean = v => typeof v === 'string' && !['undefined','null'].includes(v.trim().toLowerCase()) ? v.trim().normalize('NFC') : '';

if (ai.isTask !== true) throw new Error('Keine konkrete Aufgabenanfrage erkannt; kein Ticket angelegt.');
if (!Array.isArray(ai.assigned) || !Array.isArray(ai.subtask)) throw new Error('KI-Listen fehlen; kein Ticket angelegt.');
if (typeof ai.deadline !== 'string' || !['Herr','Frau',''].includes(ai.salutation)) throw new Error('KI-Pflichtfelder ungültig.');
for (const a of ai.assigned) {
 if (!a || !clean(a.name) || typeof a.email !== 'string') throw new Error('Ungültige zuständige Person.');
 if (a.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a.email)) throw new Error('Ungültige E-Mail einer zuständigen Person.');
}
for (const s of ai.subtask) {
 if (!s || !clean(s.value) || !Number.isInteger(s.id) || s.id < 0 || s.edit !== false || s.checked !== false) throw new Error('Ungültige Teilaufgabe.');
}

const title = clean(ai.title);
const body = typeof mail.body === 'string' ? mail.body : '';
if (!Array.isArray(ai.removeFromDescription)) throw new Error('KI-Ausgabe: removeFromDescription fehlt.');
const ranges = [];
for (const raw of new Set(ai.removeFromDescription)) {
  if (typeof raw !== 'string' || !raw.trim()) continue;
  const variants = [raw, raw.replace(/\\r\\n/g, '\n').replace(/\\n/g, '\n').replace(/\\t/g, '\t'), raw.trim()];
  let hit = null;
  for (const fragment of variants) {
    const start = body.indexOf(fragment);
    if (start >= 0 && body.indexOf(fragment, start + 1) < 0) { hit = {start, end: start + fragment.length}; break; }
  }
  if (hit) ranges.push(hit);
}
ranges.sort((a,b) => a.start - b.start);
let cursor = 0;
let description = '';
for (const range of ranges) {
  if (range.start < cursor) continue;
  description += body.slice(cursor, range.start);
  cursor = range.end;
}
description += body.slice(cursor);
description = description.trim();
if (!description) description = body.trim();
if (!title) {
  throw new Error('KI-Aufgabentitel fehlt; kein Ticket angelegt.');
}
if (!body.trim()) throw new Error('E-Mail-Text fehlt.');
if (!['User Story','Technical Task'].includes(ai.category)) throw new Error('Ungültige Kategorie.');
if (!['urgent','medium','low'].includes(ai.priority)) throw new Error('Ungültige Priorität.');
let date = clean(ai.deadline) || mail.referenceDate;
const de = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(date);
if (de) date = `${de[3]}-${de[2].padStart(2,'0')}-${de[1].padStart(2,'0')}`;
if (date) {
  const d = new Date(`${date}T00:00:00Z`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !Number.isFinite(d.getTime()) || d.toISOString().slice(0,10) !== date) {
    throw new Error('Ungültige KI-Frist: ' + date);
  }
}
const seen = new Set();
const assigned = (Array.isArray(ai.assigned) ? ai.assigned : []).filter(a => a && clean(a.name)).map(a => {
  const name = clean(a.name);
  const candidate = clean(a.email);
  const email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(candidate) ? candidate : '';
  return {name, email, avatar: name.split(/\s+/).map(x => Array.from(x)[0]).slice(0,2).join('').toUpperCase(), color:'#4589FF', assigned:true};
}).filter(a => {
  const key = (a.email || a.name).toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key); return true;
});
const subtask = (Array.isArray(ai.subtask) ? ai.subtask : []).filter(s => s && clean(s.value)).map((s,id) => ({id, value:clean(s.value), edit:false, checked:false}));
return {
  json: {
    title,
    description,
    category: ai.category,
    priority: ai.priority,
    date,
    status: 'triage',
    order: 0,
    creatorName: clean(mail.senderName) || clean(mail.senderEmail),
    creatorType: 'external',
    aiGenerated: true,
    salutation: ['Herr', 'Frau'].includes(ai.salutation)
      ? ai.salutation
      : '',
    assigned,
    subtask
  }
};
